new='''  subscribe("issue.assigned", async (payload) => {
    await notify(payload.orgId, "issue_assigned", [payload.assigneeId], {
      title: "You were assigned an issue",
      body: `Issue ${payload.issueId} is now yours`,
      href: await issueHref(payload.orgId, payload.projectId, payload.issueId),
      actorId: payload.actorId,
    });
  });

  subscribe("issue.created", async (payload) => {
    if (payload.assigneeId === null) return;
    await notify(payload.orgId, "issue_assigned", [payload.assigneeId], {
      title: "You were assigned an issue",
      body: `Issue ${payload.issueId} is now yours`,
      href: await issueHref(payload.orgId, payload.projectId, payload.issueId),
      actorId: payload.actorId,
    });
  });

  subscribe("issue.status_changed", async (payload) => {
    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    if (!issue || issue.assigneeId === null) return;
    await notify(payload.orgId, "issue_status_changed", [issue.assigneeId], {
      title: "An issue changed status",
      body: `Issue ${payload.issueId} moved from ${payload.from} to ${payload.to}`,
      href: await issueHref(payload.orgId, payload.projectId, payload.issueId),
      actorId: payload.actorId,
    });
  });

  subscribe("issue.overdue", async (payload) => {
    if (payload.assigneeId === null) return;
    await notify(payload.orgId, "issue_overdue", [payload.assigneeId], {
      title: "An issue is overdue",
      body: `Issue ${payload.issueId} was due ${payload.dueAt}`,
      href: await issueHref(payload.orgId, payload.projectId, payload.issueId),
      actorId: null,
    });
  });

  subscribe("comment.created", async (payload) => {
    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    const watchers = issue
      ? [issue.authorId, ...(issue.assigneeId ? [issue.assigneeId] : [])]
      : [];
    const href = await issueHref(
      payload.orgId,
      issue?.projectId ?? null,
      payload.issueId,
    );

    await notify(payload.orgId, "comment_created", watchers, {
      title: "New comment",
      body: `A comment was added to issue ${payload.issueId}`,
      href,
      actorId: payload.actorId,
    });

    if (payload.mentionedUserIds.length > 0) {
      await notify(
        payload.orgId,
        "comment_mention",
        payload.mentionedUserIds,
        {
          title: "You were mentioned",
          body: `You were mentioned on issue ${payload.issueId}`,
          href,
          actorId: payload.actorId,
        },
      );
    }
  });

  // The owner is told about each new member; the member is not told about themselves.
  subscribe("member.joined", async (payload) => {
    const org = requireFound(
      await orgRepo.findOrgById(payload.orgId),
      "Organization",
      payload.orgId,
    );
    if (org.ownerId === payload.userId) return;
    await notify(payload.orgId, "member_joined", [org.ownerId], {
      title: "A new member joined",
      body: `${payload.userId} joined ${org.name} as ${payload.role}`,
      href: settingsPath(org.slug, "members"),
      actorId: null,
    });
  });

  // A refused write tells the owner, once per resource until that alert is read.
  subscribe("billing.limit_exceeded", async (payload) => {
    const org = await orgRepo.findOrgById(payload.orgId);
    if (!org) return;

    const bodyPrefix = `Plan limit reached for ${payload.resource}:`;
    const pending = await notificationRepo.hasUnreadWithBodyPrefix(
      payload.orgId,
      org.ownerId,
      "plan_limit_reached",
      bodyPrefix,
    );
    if (pending) return;

    await notify(payload.orgId, "plan_limit_reached", [org.ownerId], {
      title: "Your plan is out of room",
      body: `${bodyPrefix} ${payload.used} of ${payload.limit} in use`,
      href: settingsPath(org.slug, "billing"),
      actorId: null,
    });
  });
}

/** The page the app serves for one issue, falling back to the workspace root. */
async function issueHref(
  orgId: OrgId,
  projectId: ProjectId | null,
  issueId: IssueId,
): Promise<string> {
  const org = await orgRepo.findOrgById(orgId);
  if (!org) return "/";
  const issue = await issueRepo.findIssueById(orgId, issueId);
  const project = await projectRepo.findProjectById(
    orgId,
    issue?.projectId ?? projectId ?? ("" as ProjectId),
  );
  if (!issue || !project) return orgPath(org.slug);
  return issuePath(org.slug, project.slug, issue.number);
}

