  orgId: OrgId,
  orgSlug: string | null,
  kind: SearchSubjectKind,
  subjectId: string,
): Promise<string> {
  if (orgSlug === null) return "/";
  const fallback = orgPath(orgSlug);

  if (kind === "project") {
    const project = await projectRepo.findProjectById(
      orgId,
      subjectId as Project["id"],
    );
    return project ? projectPath(orgSlug, project.slug) : fallback;
  }

  let issueId = subjectId as Issue["id"];
  if (kind === "comment") {
    const comment = await commentRepo.findCommentById(
      orgId,
      subjectId as Comment["id"],
    );
    if (!comment) return fallback;
    issueId = comment.issueId;
  }

  const issue = await issueRepo.findIssueById(orgId, issueId);
  if (!issue) return fallback;
  const project = await projectRepo.findProjectById(orgId, issue.projectId);
  return project
    ? issuePath(orgSlug, project.slug, issue.number)
    : fallback;
